const localeCodes = new Map(LOCALES.map(({ code }) => [code.toLowerCase(), code]));

export function resolveLocale(value) {
  if (typeof value !== "string") return null;
  const code = value.trim().replaceAll("_", "-").toLowerCase();
  if (localeCodes.has(code)) return localeCodes.get(code);
  if (/^zh(?:-|$)/.test(code)) {
    if (/(?:^|-)hans(?:-|$)/.test(code)) return "zh-Hans";
    return /(?:^|-)(?:hant|tw|hk|mo)(?:-|$)/.test(code) ? "zh-Hant" : "zh-Hans";
  }
  return localeCodes.get(code.split("-")[0]) || null;
}

export function translate(locale, key, values = {}) {
  const dictionary = MESSAGES[resolveLocale(locale) || "en"];
  const message = Object.hasOwn(dictionary, key) ? dictionary[key] : Object.hasOwn(MESSAGES.en, key) ? MESSAGES.en[key] : key;
  // Substitute once: literal user names containing braces never become templates.
  return message.replace(/\{([A-Za-z][A-Za-z0-9_]*)\}/g, (match, name) => Object.hasOwn(values, name) ? String(values[name]) : match);
}

export function selectedLocale(config, hass) {
  const override = typeof config?.language === "string" ? config.language.trim() : "";
  // Match DESLOC: browser language is only used by the card picker, before HA exists.
  // A present, unsupported override or HA language deliberately falls back to English.
  const requested = override && override.toLowerCase() !== "auto" ? override : hass?.locale?.language || hass?.language;
  return resolveLocale(requested) || "en";
}

const esc = (value) => String(value).replace(/[&<>"']/g, (c) => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const entityId = (value) => typeof value === "string" && /^[a-z_]+\.[a-z0-9_]+$/.test(value);

export function numericState(state) {
  if (!state || typeof state.state !== "string" || !/^[+-]?(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?$/i.test(state.state.trim())) return null;
  const value = Number(state.state);
  return Number.isFinite(value) ? value : null;
}

export function cellVoltage(state) {
  const number = numericState(state);
  if (number === null || number <= 0) return null;
  const unit = state.attributes?.unit_of_measurement;
  if (unit && unit !== "V" && unit !== "mV") return null;
  return unit === "mV" ? number / 1000 : number;
}

export function cellStats(values) {
  const present = values.filter((x) => x !== null && Number.isFinite(x));
  if (!values.length || present.length !== values.length) return {complete:false, count:present.length, min:null, max:null, delta:null};
  const min = Math.min(...present), max = Math.max(...present);
  return {complete:true, count:present.length, min, max, delta:(max-min)*1000};
}

export function normalizeConfig(config, hass) {
  const tr = (key, values) => translate(selectedLocale(config, hass), key, values);
  if (!config || !Array.isArray(config.batteries) || !config.batteries.length || config.batteries.length > 32) throw new Error(tr("errorBatteries"));
  if (config.title !== undefined && typeof config.title !== "string") throw new Error(tr("errorTitle"));
  if (config.language !== undefined && (typeof config.language !== "string" || !config.language.trim())) throw new Error(tr("errorLanguage"));
  const validateThresholds = (input) => {
    const t = {...DEFAULT_THRESHOLDS, ...input};
    if (!Object.values(t).every((x) => typeof x === "number" && Number.isFinite(x))) throw new Error(tr("errorThresholds"));
    if (!(t.cell_min > 0 && t.cell_max > t.cell_min && t.delta_warning > 0 && t.delta_critical > t.delta_warning && t.soc_low >= 0 && t.soc_warning > t.soc_low && t.soc_warning <= 100)) throw new Error(tr("errorThresholdOrder"));
    return t;
  };
  const thresholds = validateThresholds(config.thresholds);
  const batteries = config.batteries.map((b, index) => {
    if (!b || typeof b !== "object" || !Array.isArray(b.cells) || !b.cells.length || b.cells.length > 64) throw new Error(tr("errorCells", {battery:index+1}));
    for (const key of ["soc","voltage","current","power","temperature","availability"]) {
      if ((["soc","voltage"].includes(key) || b[key] !== undefined) && !entityId(b[key])) throw new Error(tr("errorEntity", {battery:index+1,field:key}));
    }
    for (const key of ["name","subtitle"]) if (b[key] !== undefined && typeof b[key] !== "string") throw new Error(tr("errorText", {battery:index+1,field:key}));
    const cells = b.cells.map((c, i) => {
      const cell = typeof c === "string" ? {entity:c} : c;
      if (!cell || !entityId(cell.entity) || (cell.name !== undefined && typeof cell.name !== "string")) throw new Error(tr("errorCell", {battery:index+1,cell:i+1}));
      return {entity:cell.entity, name:cell.name ?? String(i+1).padStart(2,"0")};
    });
    if (new Set(cells.map(c=>c.entity)).size !== cells.length) throw new Error(tr("errorDuplicate", {battery:index+1}));
    if (b.accent !== undefined && !PALETTES.includes(b.accent)) throw new Error(tr("errorAccent", {battery:index+1}));
    return {...b, cells, accent:b.accent ?? PALETTES[index%PALETTES.length], thresholds:validateThresholds({...thresholds,...b.thresholds})};
  });
  return {...config, batteries, thresholds};
}

export function batteryModel(config, states) {
  const gate = config.availability ? states[config.availability]?.state : undefined;
  const blocked = Boolean(config.availability) && !["on","online","true","connected"].includes(gate);
  const value = (key) => blocked ? null : numericState(states[config[key]]);
  const rawSoc = value("soc");
  const soc = rawSoc !== null && rawSoc >= 0 && rawSoc <= 100 ? rawSoc : null;
  const rawVoltage = value("voltage");
  const voltage = rawVoltage !== null && rawVoltage > 0 ? rawVoltage : null;
  const cells = config.cells.map(c => ({...c, value:blocked ? null : cellVoltage(states[c.entity])}));
  const metrics = {soc, voltage, current:value("current"), power:value("power"), temperature:value("temperature")};
  const values = [soc, voltage, ...["current","power","temperature"].filter(k=>config[k]).map(k=>metrics[k]), ...cells.map(c=>c.value)];
  const count = values.filter(v=>v!==null).length;
  return {...metrics, cells, stats:cellStats(cells.map(c=>c.value)), status:count===0 ? "unavailable" : count===values.length ? "available" : "partial"};
}

