export class HaJbdBmsCard extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({mode:"open"});
    this.shadowRoot.addEventListener("click", (event) => this._openEntity(event));
    this.shadowRoot.addEventListener("keydown", (event) => {
      if (["Enter"," "].includes(event.key) && event.target.closest("[data-entity]")) {event.preventDefault();this._openEntity(event);}
    });
  }
  setConfig(config) {this._config=normalizeConfig(config,this._hass);this._signature=null;this._render();}
  set hass(hass) {
    this._hass=hass;
    if (!this._config) return;
    const ids = this._config.batteries.flatMap(b=>[b.soc,b.voltage,b.current,b.power,b.temperature,b.availability,...b.cells.map(c=>c.entity)]).filter(Boolean);
    const signature = [selectedLocale(this._config,hass),...ids.map(id=>hass.states[id])];
    if (this._signature && signature.every((v,i)=>v===this._signature[i])) return;
    this._signature=signature;this._render();
  }
  getCardSize() {return 10 * Math.ceil((this._config?.batteries.length ?? 1)/2);}
  getGridOptions() {return {columns:12, rows:"auto", min_columns:6};}
  static getStubConfig() {return {type:"custom:ha-jbd-bms-card",batteries:[{soc:"sensor.replace_soc",voltage:"sensor.replace_voltage",cells:["sensor.replace_cell_1","sensor.replace_cell_2","sensor.replace_cell_3","sensor.replace_cell_4"]}]};}
  _openEntity(event) {
    const target=event.target.closest("[data-entity]");
    if (!target || !this._hass?.states[target.dataset.entity]) return;
    this.dispatchEvent(new CustomEvent("hass-more-info",{detail:{entityId:target.dataset.entity},bubbles:true,composed:true}));
  }
  _render() {
    if (!this._config || !this._hass) return;
    const language=selectedLocale(this._config,this._hass);
    this.lang=language;this.dir=LOCALES.find(locale=>locale.code===language).dir;
    const t=MESSAGES[language], states=this._hass.states;
    const tr=(key,values)=>translate(language,key,values);
    const num=(value,digits=1)=>value===null?"—":new Intl.NumberFormat(language,{minimumFractionDigits:digits,maximumFractionDigits:digits}).format(value);
    const action=(id)=>id?`class="state-action" tabindex="0" role="button" data-entity="${esc(id)}"`:"";
    const metric=(label,key,b,m,defaultUnit)=>b[key]?`<div class="metric"><div ${action(b[key])} aria-label="${esc(tr("moreInfo",{name:label}))}"><bdi class="measurement" dir="ltr"><strong>${num(m[key],key==="power"?(["kW","MW"].includes(states[b[key]]?.attributes?.unit_of_measurement)?2:0):1)}</strong><span class="unit">${esc(states[b[key]]?.attributes?.unit_of_measurement??defaultUnit)}</span></bdi><div class="metric-label">${esc(label)}</div></div></div>`:"";
    const packs=this._config.batteries.map((b,index)=>{
      const m=batteryModel(b,states), th=b.thresholds;
      const color=m.soc===null?"#8290a3":m.soc<=th.soc_low?"#e15a70":m.soc<=th.soc_warning?"#d99a25":"var(--accent)";
      const length=2*Math.PI*46;
      const spreadClass=m.stats.delta===null?"missing":m.stats.delta>=th.delta_critical-1e-9?"critical":m.stats.delta>=th.delta_warning-1e-9?"warning":"good";
      const spreadText=m.stats.delta===null?t.incomplete:spreadClass==="critical"?t.critical:spreadClass==="warning"?t.warning:t.good;
      const cellHtml=m.cells.map(c=>{
        const missing=c.value===null, out=!missing&&(c.value<th.cell_min||c.value>th.cell_max);
        const isMin=m.stats.complete&&Math.abs(c.value-m.stats.min)<1e-9;
        const isMax=m.stats.complete&&Math.abs(c.value-m.stats.max)<1e-9;
        const flag=missing?t.missing:out?t.outOfRange:(isMin&&isMax?"":isMin?t.lowest:isMax?t.highest:"");
        const fill=missing?0:Math.max(0,Math.min(100,(c.value-th.cell_min)/(th.cell_max-th.cell_min)*100));
        return `<div class="cell ${missing?"missing":out?"critical":""}" style="--fill:${fill}%"><div ${action(c.entity)} aria-label="${esc(tr("moreInfo",{name:tr("cellInfo",{name:c.name,value:missing?t.missing:`${num(c.value,3)} V`})}))}"><span class="cell-label">${esc(c.name)}</span><bdi class="measurement" dir="ltr"><strong>${num(c.value,3)}</strong><span class="unit">V</span></bdi><span class="flag">${esc(flag)}</span></div></div>`;
      }).join("");
      return `<section class="battery ${b.accent} ${m.status}" aria-label="${esc(b.name??tr("defaultBattery",{number:index+1}))}"><div class="pack-top"><div><div class="eyebrow">${esc(t.battery)} ${String(index+1).padStart(2,"0")}</div><h2>${esc(b.name??tr("defaultBattery",{number:index+1}))}</h2>${b.subtitle?`<div class="pack-subtitle">${esc(b.subtitle)}</div>`:""}</div><span class="status" title="${esc(t.status)}"><span class="dot"></span>${esc(t[m.status])}</span></div><div class="hero"><div class="ring" style="--soc-color:${color}"><svg viewBox="0 0 108 108" aria-hidden="true"><circle class="track" cx="54" cy="54" r="46"/><circle class="progress" cx="54" cy="54" r="46" stroke-dasharray="${length}" stroke-dashoffset="${length*(1-(m.soc??0)/100)}"/></svg><div class="ring-label"><div ${action(b.soc)} aria-label="${esc(tr("moreInfo",{name:t.soc}))}"><bdi class="measurement" dir="ltr"><strong>${num(m.soc,0)}</strong>${m.soc===null?"":"<small>%</small>"}</bdi><span>${esc(t.soc)}</span></div></div></div><div><div ${action(b.voltage)} aria-label="${esc(tr("moreInfo",{name:t.voltage}))}"><div class="volts">${num(m.voltage,2)}<span class="unit">${esc(states[b.voltage]?.attributes?.unit_of_measurement??"V")}</span></div><div class="metric-label">${esc(t.voltage)}</div></div></div></div>${[b.current,b.power,b.temperature].some(Boolean)?`<div class="metrics">${metric(t.current,"current",b,m,"A")}${metric(t.power,"power",b,m,"W")}${metric(t.temperature,"temperature",b,m,"°C")}</div>`:""}<div class="cell-head"><strong>${esc(t.cells)}</strong><span>${esc(tr("cellsAvailable",{available:m.stats.count,total:m.cells.length}))}</span></div><div class="cells">${cellHtml}</div><div class="spread"><div><div class="spread-label">${esc(t.spread)}</div><bdi class="measurement" dir="ltr"><strong>${num(m.stats.delta,0)}</strong><span class="unit">mV</span></bdi></div><span class="spread-pill ${spreadClass}">${esc(spreadText)}</span></div><div class="minmax"><span>${esc(t.min)} <b>${num(m.stats.min,3)} V</b></span><span>${esc(t.max)} <b>${num(m.stats.max,3)} V</b></span></div></section>`;
    }).join("");
    const focusedEntity=this.shadowRoot.activeElement?.dataset?.entity;
    const focusedIndex=focusedEntity?Array.from(this.shadowRoot.querySelectorAll("[data-entity]")).filter(el=>el.dataset.entity===focusedEntity).indexOf(this.shadowRoot.activeElement):-1;
    this.shadowRoot.innerHTML=`<style>${STYLE}</style><ha-card><header class="header"><div class="brand" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="3" y="6" width="17" height="12" rx="3"/><path d="M22 10v4M11 8l-3 5h5l-2 4"/></svg></div><div><h1>${esc(this._config.title??t.title)}</h1><p class="subtitle">${esc(t.subtitle)}</p></div><span class="badge">${esc(tr("batteryCount",{count:this._config.batteries.length}))}</span></header><div class="batteries">${packs}</div><footer class="footer">${esc(t.source)}</footer></ha-card>`;
    if(focusedEntity) Array.from(this.shadowRoot.querySelectorAll("[data-entity]")).filter(el=>el.dataset.entity===focusedEntity)[focusedIndex]?.focus({preventScroll:true});
  }
}
if (!customElements.get("ha-jbd-bms-card")) customElements.define("ha-jbd-bms-card",HaJbdBmsCard);
window.customCards=window.customCards??[];
if (!window.customCards.some(c=>c.type==="ha-jbd-bms-card")) window.customCards.push({type:"ha-jbd-bms-card",name:"JBD Battery & Cell Card",description:translate(globalThis.navigator?.language,"description"),preview:true});
console.info(`JBD BATTERY & CELL CARD ${VERSION}`);
